import struct
half=lambda x: struct.unpack('e',struct.pack('e',x))[0]
def block(x, a, an, m, mn, prefill, patched):
 calls=[]
 if a:
  if an: y=half(x+2)
  elif patched: y=half(x)
  calls.append(('attn',y)); y=y*2
  if prefill: return x,calls
  y+=1 # stub attention post-norm
  x+=y
 if m:
  if mn: y=half(x+4)
  elif patched: y=half(x)
  calls.append(('mlp',y)); y=y*3
  x+=y
 return x,calls
cases={'attention without norm':(1.0001,1,0,0,0,0),'MLP without norm, no attention':(1.0001,0,0,1,0,0),'MLP without norm after attention':(1.0001,1,1,1,0,0),'prefill without attention norm':(1.0001,1,0,1,0,1),'both norms present':(1.0001,1,1,1,1,0)}
for name, args in cases.items():
 print(name)
 for patch in (False,True):
  try: out=block(*args,patch)
  except UnboundLocalError: out='UnboundLocalError'
  print('patched' if patch else 'parent',out)
assert block(*cases['MLP without norm after attention'],False)[1][-1]==('mlp',7.0)
assert block(*cases['MLP without norm after attention'],True)[1][-1]==('mlp',8.0)
assert block(*cases['prefill without attention norm'],True)==(1.0001,[('attn',1.0)])

